  Definition wp2_pre (e : went H) (ff b c : Z) (m : mem) (t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) : machine_state :=
    MS (mkR (Z_to_bv 64 WO_ON2_RA) (Z_to_bv 64 (wS1 e)) (w_gp e) (w_tp e) t0 t1 t2 (Z_to_bv 64 (wSP e)) (Z_to_bv 64 (wS1 e))
            (Z_to_bv 64 c) a1 a2 a3 a4 a5 a6 a7
            (Z_to_bv 64 (sh ff)) (Z_to_bv 64 ff) (Z_to_bv 64 0x3f800000) (Z_to_bv 64 b) (Z_to_bv 64 99) (Z_to_bv 64 0)
            (Z_to_bv 64 0) (Z_to_bv 64 (b + 500)) (Z_to_bv 64 0) (Z_to_bv 64 (ff + 128)) t3 t4 t5 t6)
       (w_F e) (Z_to_bv 64 WO_ON2_RA) (w_fc e) None m (seg_rom asegs).

  Definition wp2_post (e : went H) (ff fp : Z) (sk : as_St H) (LBk : list block) (b c : Z) : machine_state -> Prop :=
    fun ms' => exists x5 x6 x7 x11 x12 x13 x14 x15 x16 x17 x28 x29 x30 x31 m',
      ms' = MS (mkR (Z_to_bv 64 WO_ON3_RA) (Z_to_bv 64 (wS1 e)) (w_gp e) (w_tp e) x5 x6 x7 (Z_to_bv 64 (wSP e)) (Z_to_bv 64 (wS1 e))
                    (Z_to_bv 64 100) x11 x12 x13 x14 x15 x16 x17
                    (Z_to_bv 64 (sh ff)) (Z_to_bv 64 ff) (Z_to_bv 64 0) (Z_to_bv 64 c) (Z_to_bv 64 99) (Z_to_bv 64 0)
                    (Z_to_bv 64 0) (Z_to_bv 64 (c + 100)) (Z_to_bv 64 0) (Z_to_bv 64 (ff + 128)) x28 x29 x30 x31)
               (w_F e) (Z_to_bv 64 AOPNEW) (w_fc e) None m' (seg_rom asegs)
      /\ winv H e ff fp [] sk LBk m' /\ wfc H e ff m' /\ rw_cells asegs m' (wS1 e + 48) [C8 (Z_to_bv 64 (ff + 176))]
      /\ wpst ff m' (vtrip b 500) (vtrip c 100) Z24 /\ wblk m' b 500 /\ wblk m' c 100.

  Lemma wp2 : forall (e : went H) ff fp sk LBk (p q : bptr) b c m t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6,
    wpre H e -> winv H e ff fp [] sk LBk m -> In (p, b, 500) LBk -> In (q, c, 100) LBk -> p <> q ->
    (forall bb, In bb (w_LB e) -> In bb LBk /\ blk_id bb <> q) ->
    wfc H e ff m -> rw_cells asegs m (wS1 e + 48) [C8 (Z_to_bv 64 (ff + 176))] ->
    wpst ff m (vtrip b 500) Z24 Z24 -> wblk m b 500 -> addressable m c 100 -> wr_at asegs m c 100 ->
